// Setup required components
int fd = inotify_init();
const char *path = "/path/to/watch";

// Events to monitor (example constants)
uint32_t events = IN_CREATE | IN_DELETE | IN_MODIFY;

// Watch Descriptor (returns -1 on error)
int wd;

wd = inotify_add_watch(fd, path, events);

if (wd == -1) {
    // Check errno for details
    // e.g., ENOSPC (too many watches) or EACCES
}

// wd is used to identify the watch later
// e.g., in read() results or inotify_rm_watch()
